-- Venue Live Guest "Birthday Jurassic World". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara jurassic), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'jurassic', 'Birthday Jurassic World (petualangan dino)', 'jurassic', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 130, 'center 38%',
  $t${"name":"Jurassic World","orn":"diamond","ui":{"ivory":"#F6F1E4","white":"#FFFFFF","soft":"#E7DEC4","soft2":"#C9B98A","accent":"#4F7A2A","deep":"#2F4A1A","ink":"#2A3A1A","mute":"#7A7658","line":"#DDD2B0","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#FBF8EE","ink":"#2A3A1A","accent":"#4F7A2A","gold":"#E0A21B","leaf":"#E7DEC4","hbg":"rgba(246,241,228,.94)","hline":"#C9B98A","motif":"diamond"},"hud":{"bg":"rgba(47,74,26,.88)","acc":"#FFC247","on":"#2A3A1A"},"scr":{"wine":"#2F4A1A","veil":"246,241,228"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'jurassic');
update public.live_venues set decor = $d${"speakers":{"url":"/assets/live-decor/jurassic/speakers.webp","w":2.2},"balloons":{"url":"/assets/live-decor/jurassic/balloons.webp","w":1.3,"x":3.3,"z":-18,"mirror":true},"stall_snacks":{"url":"/assets/live-decor/jurassic/stall_snacks.webp","w":2.0},"stall_candy":{"url":"/assets/live-decor/jurassic/stall_candy.webp","w":1.4},"stall_drinks":{"url":"/assets/live-decor/jurassic/stall_drinks.webp","w":4.8},"photobooth":{"url":"/assets/live-decor/jurassic/photobooth.webp","w":5.6},"claw":{"url":"/assets/live-decor/jurassic/claw.webp","w":4.4},"arch":{"url":"/assets/live-decor/jurassic/arch.webp"},"fountain":{"url":"/assets/live-decor/jurassic/fountain.webp","w":5.8},"sign":{"url":"/assets/live-decor/jurassic/sign.webp","w":1.5},"easel":{"url":"/assets/live-decor/jurassic/easel.webp","w":2.8,"x":4.6,"z":8.2},"table":{"url":"/assets/live-decor/jurassic/table.webp"},"banner":{"url":"/assets/live-decor/jurassic/banner.webp","w":1.8},"gifts":{"url":"/assets/live-decor/jurassic/gifts.webp","w":1.8},"lamp":{"url":"/assets/live-decor/jurassic/lamp.webp","w":1.3,"x":3.3,"z":-12,"mirror":true},"rope":{"url":"/assets/live-decor/jurassic/rope.webp","w":1.3,"x":3.3,"z":-6,"mirror":true},"planter":{"url":"/assets/live-decor/jurassic/planter.webp","w":1.3,"x":3.3,"z":0,"mirror":true},"bush":{"url":"/assets/live-decor/jurassic/bush.webp","w":1.3,"x":3.3,"z":6,"mirror":true},"av_host":{"url":"/assets/live-decor/jurassic/av_host.webp","name":"Rafi Kostum Dino"},"av_l1":{"url":"/assets/live-decor/jurassic/av_l1.webp","name":"Kak Penjelajah"},"av_l2":{"url":"/assets/live-decor/jurassic/av_l2.webp","name":"Kak Kacamata Bulat"},"av_l3":{"url":"/assets/live-decor/jurassic/av_l3.webp","name":"Kak Topi Goggle"},"av_p1":{"url":"/assets/live-decor/jurassic/av_p1.webp","name":"Kak Hijab Safari"},"av_p2":{"url":"/assets/live-decor/jurassic/av_p2.webp","name":"Kak Pita Hijau"},"av_p3":{"url":"/assets/live-decor/jurassic/av_p3.webp","name":"Kak Topi Bunga"}}$d$::jsonb, background_url = '/assets/live-decor/jurassic/painting.webp', active = true, updated_at = now() where key = 'jurassic';
